export const slugOf = q => q.toLowerCase().replace(/[’']/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 80)


/** Each entry is [question, answer, other ways people ask it (optional)]. */
export const ALL_QA = TOPICS.flatMap(t => t.qa.map(([q, a, also = []]) => ({ q, a, also, slug: slugOf(q), topic: t.id, topicTitle: t.title, topicPath: t.path })))
